  'OciDeck lakt niets weg in een afbeelding: gezichten, tekst op een schermafdruk en gegevens in beeld gaan mee.':
      'OciDeck ne caviarde rien dans une image : les visages, le texte d\'une capture d\'écran et les données visibles partent avec.',
  'De beeldcontrole vond hier een of meer herkenbare gezichten.':
      'Le contrôle des images a détecté ici un ou plusieurs visages reconnaissables.',
  'Naast de export komen twee bestanden te staan waarmee een ontvanger de redacties kan natrekken.':
      'Deux fichiers sont créés à côté de l\'export, permettant au destinataire de vérifier les caviardages.',
  'somt op wat er is weggelaten, zonder de waarden zelf. Dit bestand mag met het rapport mee.':
      'énumère ce qui a été omis, sans les valeurs elles-mêmes. Ce fichier peut accompagner le rapport.',
  'bevat de sleutels waarmee elke weggelakte waarde is terug te rekenen. Stuur dit bestand niet mee: dan is de redactie ongedaan gemaakt. Bewaar het bij de bron.':
      'contient les clés permettant de recalculer chaque valeur caviardée. N\'envoyez pas ce fichier : le caviardage serait annulé. Conservez-le auprès de la source.',
  'slides': 'diapositives',
  'Achtergehouden': 'Retenue',
  'Achtergehouden: strenger geclassificeerd dan de presentatie':
      'Retenue : classification plus stricte que celle de la présentation',
  '1 slide achtergehouden door haar TLP': '1 diapositive retenue par son TLP',
  'slides achtergehouden door hun TLP': 'diapositives retenues par leur TLP',
  'Deze slides gaan niet mee bij presenteren, exporteren of in het pakket. Verhoog het TLP-niveau van de presentatie bij Presentatie-info om ze mee te nemen.':
      'Ces diapositives sont exclues lors de la présentation, de l\'exportation et du paquet. Augmentez le niveau TLP de la présentation dans Infos de présentation pour les inclure.',
  'Alle slides zijn achtergehouden door hun TLP-classificatie — niets om te tonen.':
      'Toutes les diapositives sont retenues par leur classification TLP — rien à afficher.',
  'Alle slides zijn achtergehouden door hun TLP-classificatie — niets om te exporteren.':
      'Toutes les diapositives sont retenues par leur classification TLP — rien à exporter.',
  'Alle slides zijn overgeslagen of achtergehouden door hun TLP-classificatie — niets om te tonen.':
      'Toutes les diapositives sont ignorées ou retenues par leur classification TLP — rien à afficher.',
  'Alle slides zijn overgeslagen of achtergehouden door hun TLP-classificatie — niets om te exporteren.':
      'Toutes les diapositives sont ignorées ou retenues par leur classification TLP — rien à exporter.',
  'Grafiekcijfers zijn niet opgeslagen — ze staan alleen nog in dit venster:':
      'Les chiffres des graphiques n\'ont pas été enregistrés — ils n\'existent plus que dans cette fenêtre :',
  'In de browser is er geen crashherstel: sluit je dit tabblad, dan is niet-opgeslagen werk weg. Sla je presentatie zelf op.':
      'Dans le navigateur, il n\'y a pas de récupération après plantage : si vous fermez cet onglet, le travail non enregistré est perdu. Enregistrez vous-même votre présentation.',
  '•  De lokale CVE-database (je start de download zelf): OciDeck haalt de bulkgegevens op via api.github.com en het releasebestand waar dat adres naar wijst.':
      '•  La base de données CVE locale (c\'est vous qui lancez le téléchargement) : OciDeck récupère les données en masse via api.github.com et le fichier de publication vers lequel cette adresse pointe.',
  '•  CVE opzoeken (staat standaard uit): staat het aan, dan gaat je zoekterm naar de ingestelde CVE-spiegel en, als die niets vindt, naar de Europese database van ENISA en naar MITRE.':
      '•  Recherche CVE (désactivée par défaut) : si elle est activée, votre terme de recherche est envoyé au miroir CVE configuré et, s\'il ne trouve rien, à la base de données européenne de l\'ENISA et à MITRE.',
  '•  Een ingesloten YouTube- of Vimeo-video laadt de speler bij die dienst.':
      '•  Une vidéo YouTube ou Vimeo intégrée charge le lecteur auprès de ce service.',
  '•  In de browser: weigert de browser een adres rechtstreeks op te halen, dan probeert OciDeck het via de server waar de app vandaan komt; dat adres komt dan bij die server terecht.':
      '•  Dans le navigateur : si le navigateur refuse de récupérer une adresse directement, OciDeck réessaie via le serveur d\'où provient l\'application ; cette adresse parvient alors à ce serveur.',
  'Intrekken is niet vastgelegd. Bij de volgende start geldt uw toestemming weer.':
      'Le retrait n\'a pas été enregistré. Au prochain démarrage, votre consentement s\'applique de nouveau.',
  'Een tussenkop die een nieuw deel van de presentatie aankondigt. Houd het kort. Voeg via de afbeeldingsbibliotheek een achtergrondbeeld toe.':
      'Un intertitre qui annonce une nouvelle partie de la présentation. Restez concis. Ajoutez une image de fond depuis la bibliothèque d\'images.',
  'Bronnen doorzoeken…': 'Recherche dans les sources…',
  'Niet doorzocht': 'Non parcouru',
  'Deze controle draait niet in de webversie: gezichtsherkenning vergt een systeembibliotheek die de browser niet heeft. Gebruik de desktopversie om afbeeldingen op gezichten na te kijken.':
      'Cette vérification ne s\'exécute pas dans la version web : la détection de visages nécessite une bibliothèque système absente du navigateur. Utilisez la version bureau pour vérifier les visages sur les images.',
  'Het token heeft lees- en schrijfrechten op de repository nodig. Gitea en Forgejo kennen geen server-side zoeken; OciDeck zoekt lokaal.':
      'Le jeton doit avoir un accès en lecture et écriture au dépôt. Gitea et Forgejo n\'ont pas de recherche côté serveur ; OciDeck cherche en local.',
  'Het token heeft de repo-scope nodig (of fijnmazig: Contents lezen en schrijven).':
      'Le jeton doit avoir la portée repo (ou fin : Contents en lecture et écriture).',
  'Het token heeft read_repository, write_repository en read_api nodig. Server-side zoeken vereist Advanced- of Exact Search.':
      'Le jeton doit avoir read_repository, write_repository et read_api. La recherche côté serveur nécessite Advanced ou Exact Search.',
  'Snelle server-zoekopdracht — door indexeringsvertraging kan een net gewijzigd deck ontbreken.':
      'Recherche côté serveur rapide — en raison du délai d\'indexation, un deck récemment modifié peut manquer.',
  'Media blijft niet bewaard in een los .md-bestand':
      'Les médias ne sont pas conservés dans un simple fichier .md',
  'Afbeeldingen, video en audio die je in dit tabblad koos, leven alleen in het geheugen. Een los .md-bestand bewaart ze niet — bij heropenen zijn ze weg. Exporteer als .ocideck-pakket om het beeld mee te nemen.':
      'Les images, vidéos et sons que vous avez choisis dans cet onglet n\'existent qu\'en mémoire. Un simple fichier .md ne les conserve pas : ils disparaîtront à la réouverture. Exportez au format paquet .ocideck pour emporter les médias.',
  'Media verwijderd om privacyredenen':
      'Médias supprimés pour des raisons de confidentialité',
  'Afbeeldingen door AI laten taggen?': 'Laisser l\'IA étiqueter ces images ?',
  'afbeeldingen gaan naar': 'images seront envoyées à',
  'een model op dit apparaat': 'un modèle sur cet appareil',
