  'Nu': 'Maintenant',
  'Vorige rapportage': 'Rapport précédent',
  'Een scorecard toont hoogstens vijf cijfers; meer leest niet meer als een oordeel.':
      'Une fiche de résultats affiche au maximum cinq indicateurs ; au-delà, ce n\'est plus un jugement.',
  'Laat de vorige rapportage leeg als er nog geen meting was; de slide toont dan geen verandering.':
      'Laissez le rapport précédent vide s\'il n\'y avait pas encore de mesure ; la diapositive n\'affichera aucun changement.',
  'Bepaalt of een stijging groen of rood kleurt. De pijl volgt altijd de cijfers.':
      'Détermine si une hausse s\'affiche en vert ou en rouge. La flèche suit toujours les chiffres.',
  'Een paar kerncijfers met het cijfer van de vorige rapportage ernaast, zodat de verandering het verhaal vertelt. Geef per cijfer aan of stijgen goed of slecht nieuws is.':
      'Quelques indicateurs clés accompagnés du chiffre du rapport précédent, afin que l\'évolution raconte l\'histoire. Indiquez pour chacun si une hausse est une bonne ou une mauvaise nouvelle.',
  'Zekere vondsten als fout behandelen':
      'Traiter les détections certaines comme des erreurs',
  'Normaal is een zekere vondst — een BSN, een IBAN, een e-mailadres — een waarschuwing die je kunt negeren. Aan maakt er een fout van, en dan kan de export erop blokkeren als je die instelling ook aan hebt staan. Bedoeld voor omgevingen waar zulke gegevens er echt niet doorheen mogen. Onzekere vondsten blijven een waarschuwing.':
      'Normalement, une détection certaine — un numéro national, un IBAN, une adresse e-mail — est un avertissement que vous pouvez ignorer. Activé, cela devient une erreur, et l\'export peut alors être bloqué si vous avez également activé ce réglage. Prévu pour les environnements où de telles données ne doivent vraiment pas passer. Les détections incertaines restent un avertissement.',
  'Medicare-nummer — een zorggegeven': 'numéro Medicare — donnée de santé',
  'bedrijfsnummer': 'numéro de société',
  'zorgverzekeringsnummer (RAMQ) — een zorggegeven':
      'numéro d\'assurance maladie (RAMQ) — donnée de santé',
  'zorgverzekeringsnummer (OHIP) — een zorggegeven':
      'numéro d\'assurance maladie (OHIP) — donnée de santé',
  'bedrijfsnummer (BN)': 'numéro d\'entreprise (BN)',
  'zorgverlenersnummer (NPI)': 'numéro de professionnel de santé (NPI)',
  'Medicare-nummer (MBI) — een zorggegeven':
      'numéro Medicare (MBI) — une donnée de santé',
  'wacht op verbinding': 'en attente de connexion',
  'Opgeslagen op deze computer, nog niet in de repository. Gaat mee zodra er weer verbinding is — of nu, met "Wachtrij legen".':
      'Enregistré sur cet ordinateur, pas encore dans le dépôt. Il partira dès qu\'il y aura de nouveau une connexion — ou maintenant, avec « Vider la file ».',
  'Branch (optioneel)': 'Branche (facultatif)',
  'let op: de standaardbranch is': 'attention : la branche par défaut est',
  'jij werkt op': 'vous travaillez sur',
  'werkgeversnummer (EIN)': 'numéro d\'employeur (EIN)',
  'laatste vier cijfers van een SSN': 'quatre derniers chiffres d\'un SSN',
  'geboortedatum, postcode en geslacht samen — die drie wijzen meestal één persoon aan, ook zonder naam':
      'date de naissance, code postal et sexe réunis : ces trois-là désignent généralement une seule personne, même sans nom',
  'Het certificaat van deze server wordt niet vertrouwd. Bij een zelf gehoste server kun je het bekijken en vertrouwen bij Instellingen → Opslag.':
      'Le certificat de ce serveur n\'est pas approuvé. Sur un serveur auto-hébergé, vous pouvez l\'afficher et lui faire confiance dans Paramètres → Stockage.',
  'Het certificaat van de forge wordt niet vertrouwd. Bij een zelf gehoste forge kun je het bekijken en vertrouwen bij Instellingen → Opslag.':
      'Le certificat de ce forge n\'est pas approuvé. Sur un forge auto-hébergé, vous pouvez l\'afficher et lui faire confiance dans Paramètres → Stockage.',
  'Het certificaat van het endpoint wordt niet vertrouwd. Bij een zelf gehost endpoint kun je het bekijken en vertrouwen bij Instellingen → Opslag.':
      'Le certificat de ce point de terminaison n\'est pas approuvé. Sur un point de terminaison auto-hébergé, vous pouvez l\'afficher et lui faire confiance dans Paramètres → Stockage.',
  'Het certificaat van de forge wordt niet vertrouwd — zelfondertekend, verlopen, of op een andere naam gesteld.':
      'Le certificat du forge n\'est pas approuvé : auto-signé, expiré ou établi à un autre nom.',
  'Het certificaat van het endpoint wordt niet vertrouwd — zelfondertekend, verlopen, of op een andere naam gesteld.':
      'Le certificat du point de terminaison n\'est pas approuvé : auto-signé, expiré ou établi à un autre nom.',
  'creditcardnummer': 'numéro de carte bancaire',
  'beveiligingscode van een creditcard': 'code de sécurité de la carte (CVV)',
  'gegevens in de sprekersnotities — onzichtbaar op de slide, wél in de export':
      'données dans les notes de l\'orateur — invisibles sur la diapositive, mais exportées',
  'Certificaat vertrouwen?': 'Faire confiance à ce certificat ?',
  'Het certificaat van deze server is niet ondertekend door een erkende uitgever. Dat is gewoon bij een zelf gehoste server, maar het is ook hoe een afgeluisterde verbinding eruitziet.':
      'Le certificat de ce serveur n\'est pas signé par une autorité reconnue. C\'est normal pour un serveur auto-hébergé, mais c\'est aussi à quoi ressemble une connexion interceptée.',
  'Vergelijk de vingerafdruk hieronder met wat je server zelf toont. Komen ze overeen, dan praat je met de juiste machine.':
      'Comparez l\'empreinte ci-dessous avec celle qu\'affiche votre serveur. Si elles correspondent, vous parlez à la bonne machine.',
  'Uitgegeven aan': 'Délivré à',
  'Uitgegeven door': 'Délivré par',
  'Geldig tot': 'Valable jusqu\'au',
  'Vingerafdruk (SHA-256)': 'Empreinte (SHA-256)',
  'Alleen dit ene certificaat wordt vertrouwd. Vervangt de server het later, dan vraagt OciDeck het opnieuw.':
      'Seul ce certificat est approuvé. Si le serveur le remplace plus tard, OciDeck redemandera.',
  'Vertrouwen': 'Faire confiance',
  'Certificaat bekijken': 'Afficher le certificat',
  'De plekken waar je presentaties bewaart en doorzoekt — mappen op deze computer, WebDAV-servers, S3-buckets en git-repositories door elkaar. Sleep ze in de volgorde die jij wilt: de bovenste van een soort geldt als standaard.':
      'Les endroits où tu conserves et recherches tes présentations — dossiers sur cet ordinateur, serveurs WebDAV, buckets S3 et dépôts git mélangés. Fais-les glisser dans l\'ordre que tu veux : le premier d\'un type sert de valeur par défaut.',
  '•  S3-opslag: verbind je met een bucket, dan worden het endpoint, de bucketnaam en je toegangssleutel bewaard (de geheime sleutel veilig in de sleutelbos van je systeem) en worden de presentaties die je opent of opslaat naar die opslagdienst verstuurd.':
      '•  Stockage S3 : lorsque tu te connectes à un bucket, le point de terminaison, le nom du bucket et ta clé d\'accès sont conservés (la clé secrète en sécurité dans le trousseau de ton système) et les présentations que tu ouvres ou enregistres sont envoyées à ce service de stockage.',
  '•  Git-opslag: verbind je met een repository, dan wordt je toegangstoken bewaard (veilig in de sleutelbos van je systeem) en worden de presentaties die je opslaat als commits naar die server verstuurd. Een werkkopie van de repository blijft onversleuteld op dit apparaat staan.':
      '•  Stockage Git : lorsque tu te connectes à un dépôt, ton jeton d\'accès est conservé (en sécurité dans le trousseau de ton système) et les présentations que tu enregistres sont envoyées à ce serveur sous forme de commits. Une copie de travail du dépôt reste non chiffrée sur cet appareil.',
  'Voor de taal van dit deck ontbreken de ziekte- en aandoeningsnamen. Religie, politieke overtuiging en vakbondstermen worden wel herkend, en controlegetallen (BSN, IBAN, paspoort) werken altijd — maar reken er niet op dat een diagnose gevonden wordt.':
      'Les noms de maladies manquent pour la langue de cette présentation. La religion, l\'opinion politique et les termes syndicaux sont reconnus, et les motifs à chiffre de contrôle (NIR, IBAN, passeport) fonctionnent toujours — mais ne comptez pas sur la détection d\'un diagnostic.',
  'niet getest': 'non testée',
  'Werkte op': 'A fonctionné le',
  'Je bent aangemeld, maar hebt hier geen toegang. Je wachtwoord is niet het probleem — vraag de beheerder om rechten op deze map.':
      'Vous êtes connecté, mais vous n\'avez pas accès ici. Votre mot de passe n\'est pas en cause : demandez les droits sur ce dossier à l\'administrateur.',
  'Je token is geldig, maar mag dit niet. Geef het meer rechten, of wacht als de forge een limiet oplegt.':
      'Votre jeton est valide, mais n\'a pas le droit de faire cela. Donnez-lui plus de droits, ou attendez si la forge applique une limite.',
  'Het token is geldig, maar mag dit niet — geef het meer rechten op de repository.':
      'Le jeton est valide, mais n\'a pas le droit de faire cela — donnez-lui plus de droits sur le dépôt.',
  'Aangemeld, maar geen toegang — je wachtwoord is niet het probleem. Vraag rechten op deze map.':
      'Connecté, mais sans accès — votre mot de passe n\'est pas en cause. Demandez les droits sur ce dossier.',
