  'Melden': 'Signaler',
  'Geaccepteerd': 'Accepté',
  'Gewaarschuwd': 'Averti',
  'Weggelaten': 'Retiré',
  'Bewerkbaar': 'Modifiable',
  'De privacycontrole': 'Le contrôle de confidentialité',
  'OciDeck leest je dia\'s na op gegevens die privacygevoelig kunnen zijn: identificatienummers, contactgegevens, telefoonnummers, bankrekeningen, sleutels en wachtwoorden, en bijzondere persoonsgegevens. Dat gebeurt volledig op dit apparaat: er wordt niets verstuurd, en de gevonden waarde zelf komt in geen enkele melding te staan.':
      'OciDeck parcourt tes diapositives à la recherche de données potentiellement sensibles : numéros d\'identification, coordonnées, numéros de téléphone, comptes bancaires, clés et mots de passe, et catégories particulières de données personnelles. Tout se passe sur cet appareil : rien n\'est envoyé, et la valeur trouvée n\'apparaît dans aucun message.',
  'De controle garandeert niet dat alles wordt gevonden; ze verkleint de kans dat er persoonsgegevens onbedoeld uitlekken.':
      'Le contrôle ne garantit pas que tout soit trouvé ; il réduit le risque que des données personnelles fuitent involontairement.',
  'Tekst in afbeeldingen blijft buiten beeld, gelinkte bestanden worden niet geopend, en gegevens zonder herkenbaar patroon herkent geen enkele scanner. Een dia zonder meldingen is een dia waarin wíj niets hebben gevonden, niet een dia waarvan vaststaat dat er niets in staat. Wat je deelt, blijft jouw beslissing en jouw verantwoordelijkheid.':
      'Le texte dans les images reste hors de portée, les fichiers liés ne sont pas ouverts, et aucun scanner ne reconnaît des données sans motif identifiable. Une diapositive sans signalement est une diapositive où *nous* n\'avons rien trouvé, pas une diapositive dont il est prouvé qu\'elle ne contient rien. Ce que tu partages reste ta décision et ta responsabilité.',
  'telefoonnummer': 'numéro de téléphone',
  'Voor wie is deze export?': 'Pour qui est cet export ?',
  'Volledig': 'Complet',
  'Geredigeerd': 'Caviardé',
  'Voor de opdrachtgever of auditor: alleen wat je zelf op "weglaten" hebt gezet, gaat eruit. De rest blijft leesbaar, zodat een derde partij de bevindingen kan controleren.':
      'Pour le client ou l\'auditeur : seul ce que tu as marqué "omettre" est retiré. Le reste reste lisible, afin qu\'un tiers puisse vérifier les constats.',
  'Voor de bredere kring: alles wat de controle vindt gaat eruit, ook op slides die je hebt geaccepteerd. Het bestand krijgt "-geredigeerd" in de naam.':
      'Pour un public plus large : tout ce que le contrôle trouve est retiré, y compris sur les diapositives acceptées. Le fichier reçoit "-geredigeerd" dans son nom.',
  'tabel met persoonsgegevens (rijen×kolommen)':
      'tableau de données personnelles (lignes×colonnes)',
  'massa-persoonsgegevens op één slide':
      'données personnelles en masse sur une diapositive',
  'gebruikerspad met een naam erin': 'chemin utilisateur contenant un nom',
  'toegangstoken in een link': 'jeton d\'accès dans un lien',
  'persoonsgegeven in een link': 'donnée personnelle dans un lien',
  'deellink met ingebakken toegang': 'lien de partage avec accès intégré',
  'e-mailadres in een link': 'adresse e-mail dans un lien',
  'ingesloten afbeelding — wij kunnen er niet in kijken':
      'image intégrée — nous ne pouvons pas regarder dedans',
  'Je eigen gegevens': 'Tes propres coordonnées',
  'Eén per regel: je naam, e-mailadres, telefoonnummer of het domein van je organisatie. Wat hier staat wordt niet gemeld en niet geredigeerd — het is de afzender, geen bevinding. Een domein (example.org) dekt elk adres eronder.':
      'Un par ligne : ton nom, ton adresse e-mail, ton numéro de téléphone ou le domaine de ton organisation. Ce qui figure ici n\'est ni signalé ni caviardé — c\'est l\'expéditeur, pas un constat. Un domaine (example.org) couvre toutes les adresses en dessous.',
  'Bij onafgehandelde persoonsgegevens':
